// #ce0c4c2aa2fc0dbfcddfcb74 — метки приглашений в карточке бизнеса Super Admin (блок «הזמנות»).
// Данные: одноразовый бизнес «QA-AT QA-AUTO-…» с приглашением на qa+at@example.com (письмо на example.com
// не уходит → delivery_status send_failed). В конце бизнес удаляется (статус נמחק).
// ПОДМЕНА ОТВЕТА (route): статусы «התקבלה» и «פג תוקף» руками не получить (вступление требует пароля,
// истечение — 7 дней), поэтому ответ admin_get_business подменяется в браузере. Проверяется отрисовка
// меток/действий; «שליחה מחדש» после подмены вызывает НАСТОЯЩИЙ resend-invitation для реального приглашения.
import * as path from 'path';
import { Page, Route } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN_STATE });
test.describe.configure({ mode: 'serial' });

const stamp = runStamp();
const BUSINESS_NAME = `QA-AT QA-AUTO-${stamp}`;
const MANAGER_NAME = `QA-AUTO מנהל ${stamp}`;
const MANAGER_EMAIL = 'qa+at@example.com';

let businessId = '';
let originalInvitationId = '';
let originalToken = '';

type Invitation = Record<string, unknown> & { id: string; email: string; status: string; token: string | null };

const invitations = (page: Page) => page.getByRole('region', { name: 'הזמנות' });
const rowFor = (page: Page, email: string) => invitations(page).getByRole('row').filter({ hasText: email });
const statusCell = (row: ReturnType<typeof rowFor>) => row.getByRole('cell').nth(2);
const actionsCell = (row: ReturnType<typeof rowFor>) => row.getByRole('cell').nth(3);

async function openCard(page: Page) {
  const loaded = page.waitForResponse((r) => r.url().includes('/rpc/admin_get_business') && r.request().method() === 'POST');
  await page.goto(`/admin/businesses/${businessId}`);
  const res = await loaded;
  expect(res.ok()).toBeTruthy();
  await expect(page.getByRole('heading', { level: 1, name: BUSINESS_NAME })).toBeVisible();
  return (await res.json()) as { invitations: Invitation[] };
}

async function patchBusinessResponse(page: Page, mutate: (list: Invitation[]) => Invitation[]) {
  await page.route('**/rest/v1/rpc/admin_get_business', async (route: Route) => {
    const response = await route.fetch();
    const json = await response.json();
    json.invitations = mutate(json.invitations as Invitation[]);
    await route.fulfill({ response, json });
  });
}

test.describe('Жизненный цикл бизнеса — метки приглашений (#ce0c4c2aa2fc0dbfcddfcb74)', () => {
  test.afterAll(async ({ browser }) => {
    if (!businessId) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE });
    const page = await ctx.newPage();
    try {
      await page.goto(`/admin/businesses/${businessId}`);
      const status = page.getByRole('region', { name: 'סטטוס החשבון' });
      await status.getByRole('combobox', { name: 'סטטוס חדש' }).selectOption({ label: 'נמחק' });
      await status.getByRole('button', { name: 'עדכון סטטוס' }).click();
      await page.getByRole('button', { name: 'אישור', exact: true }).click();
      await expect(page.getByText('בית העסק נמחק')).toBeVisible();
    } finally {
      await ctx.close();
    }
  });

  test('ממתינה с ошибкой отправки — метка «שליחת המייל נכשלה» и действия @desktop @data #ce0c4c2aa2fc0dbfcddfcb74', async ({ page }) => {
    await page.goto('/admin/businesses/new');
    const biz = page.getByRole('group', { name: 'פרטי העסק' });
    await biz.getByRole('textbox', { name: 'שם העסק (חובה)' }).fill(BUSINESS_NAME);
    await biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' }).fill('QA-AUTO בדיקות');
    const contact = page.getByRole('group', { name: 'איש קשר' });
    await contact.getByRole('textbox', { name: 'שם איש הקשר (חובה)' }).fill('QA-AUTO איש קשר');
    await contact.getByRole('textbox', { name: 'טלפון (חובה)' }).fill('0500000000');
    await contact.getByRole('textbox', { name: 'מייל (חובה)' }).fill('qa+at-contact@example.com');
    const manager = page.getByRole('group', { name: 'מנהל/ת החשבון הראשון/ה' });
    await manager.getByRole('textbox', { name: 'שם מלא (חובה)' }).fill(MANAGER_NAME);
    await manager.getByRole('textbox', { name: 'מייל (חובה)' }).fill(MANAGER_EMAIL);

    const loaded = page.waitForResponse((r) => r.url().includes('/rpc/admin_get_business') && r.request().method() === 'POST');
    await page.getByRole('button', { name: 'יצירת בית העסק' }).click();
    await page.waitForURL(/\/admin\/businesses\/[0-9a-f-]{36}$/);
    businessId = page.url().split('/').pop()!;
    test.info().annotations.push({ type: 'test-data', description: `business ${BUSINESS_NAME} ${businessId} (удаляется в afterAll)` });

    const detail = (await (await loaded).json()) as { invitations: Invitation[] };
    const inv = detail.invitations.find((i) => i.email === MANAGER_EMAIL && i.status === 'pending');
    expect(inv, 'приглашение менеджера не создано').toBeTruthy();
    expect(inv!.delivery_status, 'предусловие: письмо на example.com не должно уходить (send_failed)').toBe('send_failed');
    originalInvitationId = inv!.id;
    originalToken = inv!.token!;

    // Источник: «מה רצוי» — «תווית כשל השליחה מוצגת רק להזמנות ממתינות»; S-05 — «שליחה חוזרת והעתקת קישור».
    const row = rowFor(page, MANAGER_EMAIL);
    await expect(statusCell(row)).toContainText('ממתינה');
    await expect(statusCell(row)).toContainText('בתוקף עד');
    await expect(statusCell(row)).toContainText('שליחת המייל נכשלה');
    await expect(row.getByRole('button', { name: 'העתקת קישור' })).toBeVisible();
    await expect(row.getByRole('button', { name: 'שליחה מחדש' })).toBeVisible();
    await expect(row.getByRole('button', { name: /^ביטול ההזמנה/ })).toBeVisible();
  });

  test('התקבלה (подмена ответа) — без метки, действие «—» @desktop @data #ce0c4c2aa2fc0dbfcddfcb74', async ({ page }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    const ACCEPTED_EMAIL = 'qa+at-accepted@example.com';
    await patchBusinessResponse(page, (list) => [
      ...list,
      { ...list[0], id: '00000000-0000-4000-8000-0000000000ac', email: ACCEPTED_EMAIL, status: 'accepted', token: null, delivery_status: 'send_failed', delivery_error: 'send_failed' },
    ]);
    await openCard(page);

    const row = rowFor(page, ACCEPTED_EMAIL);
    await expect(statusCell(row)).toContainText('התקבלה');
    await expect(statusCell(row)).not.toContainText('שליחת המייל נכשלה');
    await expect(actionsCell(row)).toHaveText('—');
    await expect(row.getByRole('button')).toHaveCount(0);
  });

  test('פג תוקף (подмена ответа) — без метки, только «שליחה מחדש»; после — ממתינה, новая ссылка работает, прежняя — «ההזמנה בוטלה» @desktop @data #ce0c4c2aa2fc0dbfcddfcb74', async ({ page, asUser }) => {
    expect(originalInvitationId, 'нужно приглашение из первого теста (serial)').toBeTruthy();
    await patchBusinessResponse(page, (list) =>
      list.map((i) => (i.id === originalInvitationId && i.status === 'pending' ? { ...i, status: 'expired', token: null, delivery_status: 'send_failed' } : i)),
    );
    await openCard(page);

    const expired = rowFor(page, MANAGER_EMAIL).filter({ hasText: 'פג תוקף' });
    await expect(statusCell(expired)).toContainText('פג תוקף');
    await expect(statusCell(expired)).not.toContainText('שליחת המייל נכשלה');
    await expect(statusCell(expired)).not.toContainText('בתוקף עד');
    await expect(expired.getByRole('button')).toHaveCount(1);
    await expect(expired.getByRole('button', { name: 'שליחה מחדש' })).toBeVisible();

    // Источник: «מה רצוי» — «הזמנה שפג תוקפה ניתנת לשליחה מחדש»; AC F-07 — новая ссылка, старая отменяется.
    const resent = page.waitForResponse((r) => r.url().includes('/functions/v1/resend-invitation'));
    await expired.getByRole('button', { name: 'שליחה מחדש' }).click();
    const resentRes = await resent;
    expect(resentRes.status()).toBe(200);
    const newToken = ((await resentRes.json()) as { invitation: { token: string } }).invitation.token;
    expect(newToken).toBeTruthy();
    expect(newToken).not.toBe(originalToken);
    await expect(rowFor(page, MANAGER_EMAIL).filter({ hasText: 'ממתינה' })).toHaveCount(1);
    await expect(rowFor(page, MANAGER_EMAIL).filter({ hasText: 'פג תוקף' })).toHaveCount(0);
    await page.unroute('**/rest/v1/rpc/admin_get_business');

    const guest = await asUser('guest');
    await guest.goto(`/invite/${newToken}`);
    await expect(guest.getByRole('heading', { level: 1, name: 'הצטרפות לחשבון העסק' })).toBeVisible();
    await expect(guest.getByRole('textbox', { name: 'סיסמה', exact: true })).toBeVisible();

    await guest.goto(`/invite/${originalToken}`);
    await expect(guest.getByRole('heading', { level: 1, name: 'ההזמנה בוטלה' })).toBeVisible();
    await expect(guest.getByRole('textbox')).toHaveCount(0);
  });

  test('בוטלה (реальная отмена приглашения с send_failed) — без метки, действие «—» @desktop @data #ce0c4c2aa2fc0dbfcddfcb74', async ({ page }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await openCard(page);
    const pending = rowFor(page, MANAGER_EMAIL).filter({ hasText: 'ממתינה' });
    await pending.getByRole('button', { name: /^ביטול ההזמנה/ }).click();
    const cancelled = page.waitForResponse((r) => r.url().includes('/rpc/cancel_invitation'));
    await page.getByRole('dialog').or(page.getByRole('alertdialog')).getByRole('button', { name: 'ביטול ההזמנה', exact: true }).click();
    expect((await cancelled).ok()).toBeTruthy();

    const detail = await openCard(page);
    const inv = detail.invitations.find((i) => i.email === MANAGER_EMAIL && i.status === 'cancelled');
    expect(inv, 'отменённое приглашение не пришло с сервера').toBeTruthy();
    expect(inv!.delivery_status, 'проверка осмысленна только при send_failed в данных').toBe('send_failed');

    const row = rowFor(page, MANAGER_EMAIL).filter({ hasText: 'בוטלה' });
    await expect(statusCell(row)).toContainText('בוטלה');
    await expect(statusCell(row)).not.toContainText('שליחת המייל נכשלה');
    await expect(actionsCell(row)).toHaveText('—');
    await expect(row.getByRole('button')).toHaveCount(0);
  });
});
